// GENERATED by medusa-integrations: copied from kit/admin/integrations.tsx by scripts/kit-sync.mjs. Do not edit by hand.
import { clx, Container, Skeleton } from "@medusajs/ui"
import { type ComponentType, type CSSProperties, useState } from "react"
import { useTranslation } from "react-i18next"

/**
 * Integrations on Medusa's own pages, the same in every plugin.
 *
 * Every plugin of the repo ships this file (kit). Each one registers what it
 * has to show (for now: a tab on the order page) in a registry shared through
 * `globalThis`, and each one has the same widget in the zone. Only the first
 * plugin that claimed the zone renders, so the page gets one card with a tab
 * per installed integration, never one card per plugin.
 *
 * The registry key carries a version: plugins built with an older kit keep
 * working, and a breaking change gets a new key.
 */

type IconComponent = ComponentType<{ style?: CSSProperties; color?: string; className?: string }>

/** The state colour-coding used on dots: green ok, orange attention, red error, blue info, grey nothing. */
export type Level = "ok" | "info" | "warn" | "error" | "none"

const LEVEL_COLOR: Record<Level, string> = {
  ok: "var(--tag-green-icon)",
  info: "var(--tag-blue-icon)",
  warn: "var(--tag-orange-icon)",
  error: "var(--tag-red-icon)",
  none: "var(--tag-neutral-icon)",
}

/** Errors first, then what needs attention: a tab in that state opens first. */
const LEVEL_RANK: Record<Level, number> = { error: 0, warn: 1, info: 2, ok: 3, none: 4 }

/** How an integration looks: the same tile as its sidebar entry. */
export type Brand = {
  /** Translation key of the name (in the plugin's own namespace), or the name itself. */
  label: string
  /** Icon on a coloured tile... */
  icon?: IconComponent
  color?: string
  /** ...or the service's logo. `logoFill` for logos that are a coloured square themselves. */
  logo?: string
  logoFill?: boolean
}

/** What a tab reports: whether it applies to this order, and its colour. */
export type TabState = { visible: boolean; level: Level; loading?: boolean }

/** The order page, as Medusa passes it to widgets (only what tabs read). */
export type OrderLike = { id: string } & Record<string, any>

export type OrderTab = {
  /** The plugin's namespace, e.g. "stripe". */
  id: string
  brand: Brand
  /** Lower comes first (payments, shipping, documents, messages, the rest). */
  order: number
  /** A React hook: called on every render of the card, in a stable order. */
  useState: (order: OrderLike) => TabState
  Panel: ComponentType<{ order: OrderLike }>
}

type Registry = { orderTabs: OrderTab[]; owners: Record<string, string> }

const KEY = Symbol.for("bitshaft.medusa-integrations.registry.v1")

function registry(): Registry {
  const store = globalThis as typeof globalThis & { [KEY]?: Registry }
  return (store[KEY] ??= { orderTabs: [], owners: {} })
}

/** Registers the plugin's tab on the order page (once, at module load of its widget). */
export function registerOrderTab(tab: OrderTab): void {
  const r = registry()
  if (r.orderTabs.some((t) => t.id === tab.id)) return
  r.orderTabs.push(tab)
  r.orderTabs.sort((a, b) => a.order - b.order || a.id.localeCompare(b.id))
}

export const ORDER_ZONE = "order.details.before"

/** The first plugin to claim a zone renders its card; the others render nothing there. */
export function claimZone(zone: string, owner: string): void {
  registry().owners[zone] ??= owner
}

const isOwner = (zone: string, owner: string) => registry().owners[zone] === owner

/** The coloured tile of an integration, in any size. */
export const BrandTile = ({ brand, size = 20 }: { brand: Brand; size?: number }) => {
  const Icon = brand.icon
  if (brand.logo) {
    return (
      <span
        aria-hidden
        className={clx(
          "flex shrink-0 items-center justify-center overflow-hidden rounded-[4px] shadow-borders-base",
          !brand.logoFill && "bg-white p-px"
        )}
        style={{ width: size, height: size }}
      >
        <img src={brand.logo} alt="" className={clx("size-full", brand.logoFill ? "object-cover" : "object-contain")} />
      </span>
    )
  }
  return (
    <span
      aria-hidden
      className="flex shrink-0 items-center justify-center rounded-[4px]"
      style={{ width: size, height: size, backgroundColor: brand.color, color: "#ffffff" }}
    >
      {Icon && <Icon color="currentColor" style={{ width: size * 0.7, height: size * 0.7 }} />}
    </span>
  )
}

export const LevelDot = ({ level, className }: { level: Level; className?: string }) => (
  <span
    aria-hidden
    className={clx("inline-block size-1.5 shrink-0 rounded-full", className)}
    style={{ backgroundColor: LEVEL_COLOR[level] }}
  />
)

/**
 * The order page card: one tab per integration that applies to the order,
 * each with its brand tile and a dot in its state's colour. Rendered by the
 * plugin that claimed the zone; `owner` is the calling plugin's namespace.
 */
export const OrderIntegrations = ({ owner, order }: { owner: string; order: OrderLike }) =>
  isOwner(ORDER_ZONE, owner) ? <OrderCard order={order} /> : null

const OrderCard = ({ order }: { order: OrderLike }) => {
  const { t } = useTranslation()
  // A snapshot: every tab's hook is called on every render, in this order.
  const [tabs] = useState(() => [...registry().orderTabs])
  const states = tabs.map((tab) => tab.useState(order))
  const [selected, setSelected] = useState<string | null>(null)

  const shown = tabs.map((tab, i) => ({ tab, state: states[i] })).filter(({ state }) => state.visible || state.loading)
  if (!shown.length) return null

  const ready = shown.filter(({ state }) => state.visible)
  const fallback = [...ready].sort((a, b) => LEVEL_RANK[a.state.level] - LEVEL_RANK[b.state.level])[0]?.tab.id ?? null
  const active = ready.find(({ tab }) => tab.id === selected)?.tab ?? ready.find(({ tab }) => tab.id === fallback)?.tab
  const Panel = active?.Panel

  return (
    <Container className="overflow-hidden divide-y p-0">
      <div role="tablist" className="flex flex-wrap items-center gap-1 bg-ui-bg-subtle px-4 py-2">
        {shown.map(({ tab, state }) => {
          const label = t(tab.brand.label, { defaultValue: tab.brand.label })
          const isActive = tab.id === active?.id
          return state.visible ? (
            <button
              key={tab.id}
              type="button"
              role="tab"
              aria-selected={isActive}
              onClick={() => setSelected(tab.id)}
              className={clx(
                "txt-compact-small-plus flex items-center gap-x-2 rounded-md px-2.5 py-1.5 transition-fg outline-none",
                "focus-visible:shadow-borders-focus",
                isActive
                  ? "bg-ui-bg-base text-ui-fg-base shadow-borders-interactive-with-active"
                  : "text-ui-fg-subtle hover:bg-ui-bg-base-hover hover:text-ui-fg-base"
              )}
            >
              <BrandTile brand={tab.brand} size={18} />
              {label}
              <LevelDot level={state.level} />
            </button>
          ) : (
            <span key={tab.id} className="flex items-center gap-x-2 px-2.5 py-1.5 opacity-60">
              <BrandTile brand={tab.brand} size={18} />
              <Skeleton className="h-3 w-12" />
            </span>
          )
        })}
      </div>
      <div role="tabpanel">{active && Panel ? <Panel order={order} /> : <Skeleton className="m-6 h-24" />}</div>
    </Container>
  )
}
